-- Phase 1: full ShiftWorkr domain schema (see PLAN.md section 4).
-- Conventions: UUID PKs (client-generated by Hibernate), timestamptz for instants,
-- wall-clock Europe/Berlin dates as DATE/TIME, enums as VARCHAR (never ordinals).
-- V1__baseline (flyway_baseline_probe) is left untouched.

-- ============ Ward ============
CREATE TABLE ward (
  id UUID PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  code VARCHAR(20) NOT NULL UNIQUE,
  active BOOLEAN NOT NULL DEFAULT TRUE
);

-- ============ Roster period (Draft/Published/Locked per ward + month) ============
CREATE TABLE roster_period (
  id UUID PRIMARY KEY,
  ward_id UUID NOT NULL REFERENCES ward(id),
  year INT NOT NULL CHECK (year BETWEEN 2000 AND 2100),
  month INT NOT NULL CHECK (month BETWEEN 1 AND 12),
  status VARCHAR(20) NOT NULL CHECK (status IN ('DRAFT', 'PUBLISHED', 'LOCKED')),
  published_at TIMESTAMPTZ,
  published_by UUID,
  CONSTRAINT uq_roster_period_ward_ym UNIQUE (ward_id, year, month)
);
CREATE INDEX idx_roster_period_ward ON roster_period (ward_id);

-- ============ Staff member (2 roles; lead is a flag, not a role) ============
CREATE TABLE staff_member (
  id UUID PRIMARY KEY,
  ward_id UUID REFERENCES ward(id),
  email VARCHAR(255) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  first_name VARCHAR(100) NOT NULL,
  last_name VARCHAR(100) NOT NULL,
  role VARCHAR(20) NOT NULL CHECK (role IN ('ADMIN', 'NURSE')),
  qualification VARCHAR(20) NOT NULL CHECK (qualification IN ('RN', 'ICU_SPECIALIST', 'ASSISTANT')),
  lead_qualified BOOLEAN NOT NULL DEFAULT FALSE,
  target_weekly_hours INT NOT NULL CHECK (target_weekly_hours BETWEEN 10 AND 48),
  active BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE INDEX idx_staff_ward ON staff_member (ward_id);

-- Roster period publisher references staff (added after staff_member exists to keep
-- creation order simple; RESTRICT delete protects published history).
ALTER TABLE roster_period
  ADD CONSTRAINT fk_roster_period_published_by FOREIGN KEY (published_by) REFERENCES staff_member(id);

-- ============ Shift type (N crosses midnight via end_day_offset=1) ============
CREATE TABLE shift_type (
  id UUID PRIMARY KEY,
  code VARCHAR(10) NOT NULL UNIQUE,
  name VARCHAR(50) NOT NULL,
  start_time TIME NOT NULL,
  end_time TIME NOT NULL,
  end_day_offset INT NOT NULL CHECK (end_day_offset IN (0, 1)),
  break_duration_minutes INT NOT NULL DEFAULT 0 CHECK (break_duration_minutes >= 0),
  color_code VARCHAR(20) NOT NULL
);

-- ============ Shift assignment (OFF/VACATION/SICK are explicit rows) ============
CREATE TABLE shift_assignment (
  id UUID PRIMARY KEY,
  ward_id UUID NOT NULL REFERENCES ward(id),
  staff_member_id UUID NOT NULL REFERENCES staff_member(id),
  shift_type_id UUID REFERENCES shift_type(id),
  shift_date DATE NOT NULL,
  status VARCHAR(20) NOT NULL
    CHECK (status IN ('SCHEDULED', 'SWAP_PENDING', 'COMPLETED', 'OFF', 'VACATION', 'SICK', 'ABSENT')),
  note TEXT,
  version INT NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- One active row per staff per day; ABSENT rows are audit traces and may repeat.
CREATE UNIQUE INDEX idx_unique_active_assignment
  ON shift_assignment (staff_member_id, shift_date)
  WHERE status IN ('SCHEDULED', 'SWAP_PENDING', 'COMPLETED', 'OFF', 'VACATION', 'SICK');
CREATE INDEX idx_assignment_ward_date ON shift_assignment (ward_id, shift_date);

-- ============ Swap request (1:1 direct + OPEN board via nullable target/request) ============
CREATE TABLE swap_request (
  id UUID PRIMARY KEY,
  requester_id UUID NOT NULL REFERENCES staff_member(id),
  target_colleague_id UUID REFERENCES staff_member(id),
  offered_shift_id UUID NOT NULL REFERENCES shift_assignment(id),
  requested_shift_id UUID REFERENCES shift_assignment(id),
  status VARCHAR(20) NOT NULL
    CHECK (status IN ('PENDING_COLLEAGUE', 'PENDING_ADMIN', 'APPROVED', 'REJECTED', 'CANCELLED', 'EXPIRED')),
  reason VARCHAR(500),
  admin_note VARCHAR(500),
  compliance_override BOOLEAN NOT NULL DEFAULT FALSE,
  override_reason VARCHAR(500),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  decided_at TIMESTAMPTZ,
  decided_by UUID REFERENCES staff_member(id)
);
CREATE INDEX idx_swap_status ON swap_request (status);
CREATE INDEX idx_swap_requester ON swap_request (requester_id);

-- ============ Leave request ============
CREATE TABLE leave_request (
  id UUID PRIMARY KEY,
  staff_id UUID NOT NULL REFERENCES staff_member(id),
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  type VARCHAR(10) NOT NULL CHECK (type IN ('VAC', 'SICK', 'EDU')),
  status VARCHAR(20) NOT NULL CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED')),
  note VARCHAR(500),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  decided_at TIMESTAMPTZ,
  CONSTRAINT chk_leave_dates CHECK (end_date >= start_date)
);
CREATE INDEX idx_leave_staff_dates ON leave_request (staff_id, start_date, end_date);

-- ============ Shift requirement (weekly pattern + holiday/specific overrides) ============
CREATE TABLE shift_requirement (
  id UUID PRIMARY KEY,
  ward_id UUID NOT NULL REFERENCES ward(id),
  shift_type_id UUID NOT NULL REFERENCES shift_type(id),
  day_of_week VARCHAR(10) CHECK (day_of_week IN ('MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY')),
  specific_date DATE,
  valid_from DATE,
  valid_to DATE,
  min_staff_count INT NOT NULL CHECK (min_staff_count >= 0),
  min_lead_count INT NOT NULL CHECK (min_lead_count >= 0),
  CONSTRAINT chk_lead_lte_staff CHECK (min_lead_count <= min_staff_count),
  CONSTRAINT chk_requirement_scope CHECK (day_of_week IS NOT NULL OR specific_date IS NOT NULL)
);
CREATE INDEX idx_requirement_ward_dow ON shift_requirement (ward_id, day_of_week);

-- ============ Audit log (every state transition, override, publish) ============
CREATE TABLE audit_log (
  id UUID PRIMARY KEY,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  actor_id UUID REFERENCES staff_member(id),
  action VARCHAR(60) NOT NULL,
  entity_type VARCHAR(60) NOT NULL,
  entity_id UUID,
  details JSONB
);
CREATE INDEX idx_audit_entity ON audit_log (entity_type, entity_id);
